{
  "name": "@vasilvestre/opencode-dream-memory",
  "version": "0.5.0",
  "description": "Injects shared and per-project memory files into every OpenCode request, so they survive context compaction.",
  "keywords": [
    "opencode-plugin",
    "opencode",
    "memory",
    "context",
    "compaction"
  ],
  "license": "MIT",
  "author": {
    "name": "vasilvestre",
    "url": "https://github.com/vasilvestre"
  },
  "homepage": "https://github.com/vasilvestre/opencode-dream-memory",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/vasilvestre/opencode-dream-memory.git"
  },
  "type": "module",
  "main": "./.opencode/plugins/dream-memory.js",
  "exports": {
    ".": "./.opencode/plugins/dream-memory.js",
    "./plugin": "./.opencode/plugins/dream-memory.js"
  },
  "scripts": {
    "test": "node scripts/check-plugin.mjs && sh scripts/check-corpus.sh && sh scripts/check-discover.sh"
  },
  "files": [
    ".opencode/",
    "dream/",
    "install.sh",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  }
}
